export interface Account {
  /**
   * Account ID.
   * @format GUID
   */
  accountId?: string;
  /** Slug used in the prefix of a free site's URL. */
  slug?: string;
  /** Account name for display. */
  accountName?: string | null;
  /**
   * Deprecated. Use `accountProperties. accountImg` instead.
   * @deprecated
   */
  accountImg?: string | null;
  /** Account status. */
  status?: AccountStatusWithLiterals;
  /** Account owner's user ID. */
  accountOwner?: string;
  /** Additional account properties. */
  accountProperties?: AccountProperties;
  /** Date and time the account was created. */
  dateCreated?: Date | null;
  /** Date and time the account was last updated. */
  dateUpdated?: Date | null;
}

/** enum with all available statuses of account */
export enum AccountStatus {
  ACTIVE = 'ACTIVE',
  BLOCKED = 'BLOCKED',
  DELETED = 'DELETED',
}

/** @enumType */
export type AccountStatusWithLiterals =
  | AccountStatus
  | 'ACTIVE'
  | 'BLOCKED'
  | 'DELETED';

/** All relevant account properties */
export interface AccountProperties {
  /** Whether this account is a team account. */
  isTeam?: boolean;
  /** Account image for display. Relevant primarily for accounts with [custom branding](https://support.wix.com/en/article/wix-studio-setting-up-custom-branding). */
  accountImg?: string | null;
  /** Account banner for display. Relevant primarily for accounts with [custom branding](https://support.wix.com/en/article/wix-studio-setting-up-custom-branding). */
  accountBanner?: string | null;
  /** Account logo, displayed on customer sites that inherit the custom branding. */
  accountLogo?: string | null;
  /** Account [custom branding](https://support.wix.com/en/article/wix-studio-setting-up-custom-branding) status. */
  coBranding?: CoBrandingWithLiterals;
  /** Account website URL. This URL is displayed on customer sites that inherit the custom branding. */
  websiteUrl?: string | null;
  /** ID of parent account to this account, if relevant. */
  parentAccountId?: string | null;
  /** Whether the account's data should be stored locally. */
  dataLocality?: boolean;
  /**
   * The type of this account, as an open string drawn from the Wix user-type vocabulary
   * (e.g. `Nautilus`, `Wixel`). Mirrors the user's user type; unset for regular Wix accounts.
   * Once set, it can be updated but not cleared.
   * @maxLength 100
   */
  accountType?: string | null;
}

/** co branding flag options for account */
export enum CoBranding {
  /** The account does not have custom branding. */
  None = 'None',
  /** The account has custom branding. */
  CoBranded = 'CoBranded',
  /** The account is a contributor of an account with custom branding and was created because of the contributor invite. */
  CoBranded_Customer_New = 'CoBranded_Customer_New',
  /** The account is a contributor of an account with custom branding and existed before receiving the contributor invite. */
  CoBranded_Customer_Existing = 'CoBranded_Customer_Existing',
}

/** @enumType */
export type CoBrandingWithLiterals =
  | CoBranding
  | 'None'
  | 'CoBranded'
  | 'CoBranded_Customer_New'
  | 'CoBranded_Customer_Existing';

